            val value = element.jsonObject
            ReturnRightsActivationFrozenVariantV1(value.getValue("id").jsonPrimitive.content,
                value.getValue("name").jsonPrimitive.content, value.getValue("input").jsonObject,
                value.getValue("expected").jsonPrimitive.content)
